import Padding = require( './index' );


// TESTS //

// The function returns a padding instance...
{
	new Padding(); // $ExpectType Padding
	new Padding( {} ); // $ExpectType Padding
	new Padding( { 'top': 10 } ); // $ExpectType Padding
	new Padding( { 'bottom': 10, 'left': 20, 'right': 30, 'top': 40 } ); // $ExpectType Padding

	Padding(); // $ExpectType Padding
	Padding( {} ); // $ExpectType Padding
	Padding( { 'top': 10 } ); // $ExpectType Padding
	Padding( { 'bottom': 10, 'left': 20, 'right': 30, 'top': 40 } ); // $ExpectType Padding
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	new Padding( '5' ); // $ExpectError
	new Padding( 5 ); // $ExpectError
	new Padding( true ); // $ExpectError
	new Padding( false ); // $ExpectError
	new Padding( null ); // $ExpectError
	new Padding( [] ); // $ExpectError
	new Padding( ( x: number ): number => x ); // $ExpectError

	Padding( '5' ); // $ExpectError
	Padding( 5 ); // $ExpectError
	Padding( true ); // $ExpectError
	Padding( false ); // $ExpectError
	Padding( null ); // $ExpectError
	Padding( [] ); // $ExpectError
	Padding( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a `bottom` option which is not a number...
{
	new Padding( { 'bottom': '5' } ); // $ExpectError
	new Padding( { 'bottom': true } ); // $ExpectError
	new Padding( { 'bottom': false } ); // $ExpectError
	new Padding( { 'bottom': null } ); // $ExpectError
	new Padding( { 'bottom': [] } ); // $ExpectError
	new Padding( { 'bottom': {} } ); // $ExpectError
	new Padding( { 'bottom': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `left` option which is not a number...
{
	new Padding( { 'left': '5' } ); // $ExpectError
	new Padding( { 'left': true } ); // $ExpectError
	new Padding( { 'left': false } ); // $ExpectError
	new Padding( { 'left': null } ); // $ExpectError
	new Padding( { 'left': [] } ); // $ExpectError
	new Padding( { 'left': {} } ); // $ExpectError
	new Padding( { 'left': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `right` option which is not a number...
{
	new Padding( { 'right': '5' } ); // $ExpectError
	new Padding( { 'right': true } ); // $ExpectError
	new Padding( { 'right': false } ); // $ExpectError
	new Padding( { 'right': null } ); // $ExpectError
	new Padding( { 'right': [] } ); // $ExpectError
	new Padding( { 'right': {} } ); // $ExpectError
	new Padding( { 'right': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `top` option which is not a number...
{
	new Padding( { 'top': '5' } ); // $ExpectError
	new Padding( { 'top': true } ); // $ExpectError
	new Padding( { 'top': false } ); // $ExpectError
	new Padding( { 'top': null } ); // $ExpectError
	new Padding( { 'top': [] } ); // $ExpectError
	new Padding( { 'top': {} } ); // $ExpectError
	new Padding( { 'top': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided more than one argument...
{
	new Padding( {}, {} ); // $ExpectError
	Padding( {}, {} ); // $ExpectError
}

// A padding instance has numeric padding properties...
{
	const padding = new Padding();

	const bottom = padding.bottom; // $ExpectType number
	const left = padding.left; // $ExpectType number
	const right = padding.right; // $ExpectType number
	const top = padding.top; // $ExpectType number

	if ( bottom + left + right + top < 0 ) {
		throw new Error( 'unexpected error' );
	}
}

// The compiler throws an error if a padding property is assigned a value which is not a number...
{
	const padding = new Padding();

	padding.bottom = '5'; // $ExpectError
	padding.left = true; // $ExpectError
	padding.right = null; // $ExpectError
	padding.top = []; // $ExpectError
}

// A padding instance has a read-only `properties` property...
{
	const padding = new Padding();

	const props = padding.properties; // $ExpectType string[]
	if ( props.length !== 4 ) {
		throw new Error( 'unexpected error' );
	}
	padding.properties = [ 'top' ]; // $ExpectError
}

// A padding instance has a `toJSON` method which returns a JSON object...
{
	const padding = new Padding();

	padding.toJSON(); // $ExpectType JSON
}

// The compiler throws an error if the `toJSON` method is provided arguments...
{
	const padding = new Padding();

	padding.toJSON( {} ); // $ExpectError
}
